Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnspratosWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnspratosWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnspratosWWGridState")) Endif
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFPRATOCODIGO" &TFpratoCodigo.FromString(&GridStateFilterValue.Value) &TFpratoCodigo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFPRATODSCRICAO" &TFpratoDscricao.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPRATODSCRICAO_SEL" &TFpratoDscricao_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPRATOTIPOREFEICAO" &TFpratoTipoRefeicao.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPRATOTIPOREFEICAO_SEL" &TFpratoTipoRefeicao_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPRATOSTATUS_SEL" &TFpratoStatus_SelsJson = &GridStateFilterValue.Value &TFpratoStatus_Sels.FromJson(&TFpratoStatus_SelsJson) EndCase EndFor If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'PRATOCODIGO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &pratoCodigo1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'PRATODSCRICAO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &pratoDscricao1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'PRATOCOMFREEZER' &pratoComFreezer1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'PRATOCOZINHACENTRAL' &pratoCozinhaCentral1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'PRATOFORNO' &pratoForno1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'PRATOREPETICAO' &pratoRepeticao1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'PRATOTIPOREFEICAO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &pratoTipoRefeicao1.FromString(&GridStateDynamicFilter.Value) EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'PRATOCODIGO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &pratoCodigo2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'PRATODSCRICAO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &pratoDscricao2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'PRATOCOMFREEZER' &pratoComFreezer2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'PRATOCOZINHACENTRAL' &pratoCozinhaCentral2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'PRATOFORNO' &pratoForno2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'PRATOREPETICAO' &pratoRepeticao2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'PRATOTIPOREFEICAO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &pratoTipoRefeicao2.FromString(&GridStateDynamicFilter.Value) EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'PRATOCODIGO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &pratoCodigo3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'PRATODSCRICAO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &pratoDscricao3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'PRATOCOMFREEZER' &pratoComFreezer3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'PRATOCOZINHACENTRAL' &pratoCozinhaCentral3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'PRATOFORNO' &pratoForno3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'PRATOREPETICAO' &pratoRepeticao3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'PRATOTIPOREFEICAO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &pratoTipoRefeicao3.FromString(&GridStateDynamicFilter.Value) EndCase EndIf EndIf EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadpratoDscricaoOptions'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&TFpratoDscricao = &SearchTxt &TFpratoDscricao_Sel.SetEmpty() For Each trnspratos Order pratoDscricao using trnspratosWWDS(&DynamicFiltersSelector1, &DynamicFiltersOperator1, &pratoCodigo1, &pratoDscricao1, &pratoComFreezer1, &pratoCozinhaCentral1 , &pratoForno1, &pratoRepeticao1, &pratoTipoRefeicao1, &DynamicFiltersEnabled2, &DynamicFiltersSelector2, &DynamicFiltersOperator2 , &pratoCodigo2, &pratoDscricao2, &pratoComFreezer2, &pratoCozinhaCentral2, &pratoForno2, &pratoRepeticao2 , &pratoTipoRefeicao2, &DynamicFiltersEnabled3, &DynamicFiltersSelector3, &DynamicFiltersOperator3, &pratoCodigo3, &pratoDscricao3 , &pratoComFreezer3, &pratoCozinhaCentral3, &pratoForno3, &pratoRepeticao3, &pratoTipoRefeicao3, &TFpratoCodigo , &TFpratoCodigo_To, &TFpratoDscricao, &TFpratoDscricao_Sel, &TFpratoTipoRefeicao, &TFpratoTipoRefeicao_Sel, &TFpratoStatus_Sels) Where prefCodigo = &prefCodigo
&count = 0 For Each trnspratos Order pratoDscricao &count += 1 EndFor If not pratoDscricao.IsEmpty() &Option = pratoDscricao
&Options.Add(&Option) &OptionIndexes.Add(trim(&count.ToFormattedString())) EndIf If &Options.Count = 50 Exit EndIf EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadpratoTipoRefeicaoOptions'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&TFpratoTipoRefeicao = &SearchTxt &TFpratoTipoRefeicao_Sel.SetEmpty() For Each trnspratos Order pratoTipoRefeicao using trnspratosWWDS(&DynamicFiltersSelector1, &DynamicFiltersOperator1, &pratoCodigo1, &pratoDscricao1, &pratoComFreezer1, &pratoCozinhaCentral1 , &pratoForno1, &pratoRepeticao1, &pratoTipoRefeicao1, &DynamicFiltersEnabled2, &DynamicFiltersSelector2, &DynamicFiltersOperator2 , &pratoCodigo2, &pratoDscricao2, &pratoComFreezer2, &pratoCozinhaCentral2, &pratoForno2, &pratoRepeticao2 , &pratoTipoRefeicao2, &DynamicFiltersEnabled3, &DynamicFiltersSelector3, &DynamicFiltersOperator3, &pratoCodigo3, &pratoDscricao3 , &pratoComFreezer3, &pratoCozinhaCentral3, &pratoForno3, &pratoRepeticao3, &pratoTipoRefeicao3, &TFpratoCodigo , &TFpratoCodigo_To, &TFpratoDscricao, &TFpratoDscricao_Sel, &TFpratoTipoRefeicao, &TFpratoTipoRefeicao_Sel, &TFpratoStatus_Sels) Where prefCodigo = &prefCodigo
&count = 0 For Each trnspratos Order pratoTipoRefeicao &count += 1 EndFor If not refTipDescricao.IsEmpty() &Option = pratoTipoRefeicao.ToString() &OptionDesc = refTipDescricao
&InsertIndex = 1 Do while &InsertIndex <= &Options.Count AND &OptionsDesc.Item(&InsertIndex) < &OptionDesc &InsertIndex = &InsertIndex + 1 EndDo &Options.Add(&Option, &InsertIndex) &OptionsDesc.Add(&OptionDesc, &InsertIndex) &OptionIndexes.Add(trim(&count.ToFormattedString()), &InsertIndex) EndIf If &Options.Count = 50 Exit EndIf EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub

